INSERT INTO tpd_audit (at, user, action, ref_type, ref_id, reason) SELECT DATE_FORMAT(NOW(3), '%Y-%m-%d %H:%i:%s.%f'), 'claude-technical (reset script run in phpMyAdmin; isolated test instance)', 'brc_setup', 'brc_setup', 'v1 (demo reset)', 'Daily Bank Reconciliation demonstration data put back to the snapshot of 12 Oct 2026 (before r2)' FROM DUAL;
