-- brc_day: 1 row(s)
DELETE FROM account_runing WHERE ID BETWEEN 99980000 AND 99989999;
-- account_runing (dummy rows): 15
DELETE FROM tpd_bank_account WHERE label LIKE 'TEST % account (dummy)';
DELETE FROM account_posting WHERE L_Code IN ('1-6-8-29901','1-6-8-29902','1-6-8-29903','1-6-8-29904','2-9-99-29909');
SELECT (SELECT COUNT(*) FROM brc_statement) AS statements, (SELECT COUNT(*) FROM brc_line) AS lines_, (SELECT COUNT(*) FROM brc_match) AS matches, (SELECT COUNT(*) FROM brc_mark) AS marks, (SELECT COUNT(*) FROM brc_correction) AS corrections, (SELECT COUNT(*) FROM brc_day) AS days, (SELECT COUNT(*) FROM account_runing WHERE ID BETWEEN 99980000 AND 99989999) AS dummy_rows, (SELECT v FROM tpd_meta WHERE k = 'brc_schema_version') AS schema_version;
DROP TEMPORARY TABLE IF EXISTS brc_reset_guard;
